"""Explicit interfaces and observable examples for every Agent exercise."""

def param(name, type, description):
    return dict(name=name, type=type, description=description)


def spec(function, parameters, returns, requirements, input, output, explanation):
    return dict(function=function, parameters=parameters, returns=returns,
                requirements=requirements,
                example=dict(input=input, output=output, explanation=explanation))

MODEL = '已创建的聊天模型对象，运行器会传入它。通过 `invoke(...)` 发送问题，返回消息的 `content` 保存回答文字。'
CONFIG = '连接信息字典，`model` 是模型名称，`api_key` 是密钥，`base_url` 是服务地址。运行器从 `.env` 中读取对应的 `MODEL_NAME`、`MODEL_API_KEY`、`MODEL_BASE_URL` 字段后传入。'
MESSAGE = 'LangChain 消息对象列表，`SystemMessage` 保存系统说明，`HumanMessage` 保存用户问题，`AIMessage` 保存模型回答，`ToolMessage` 保存工具结果。'
